import sys
from collections import defaultdict, deque

def find_shortest_cycle(n, file_names, sections):
    graph = defaultdict(list)
    for section in sections:
        name = section[0]
        for dep in section[2:]:
            graph[name].append(dep)

    def bfs(start):
        queue = deque([(start, [start])])
        visited = {start: [start]}
        while queue:
            node, path = queue.popleft()
            for neighbor in graph[node]:
                if neighbor == start:
                    return path + [start]
                if neighbor not in visited:
                    visited[neighbor] = path + [neighbor]
                    queue.append((neighbor, path + [neighbor]))
        return None

    shortest_cycle = None
    for file_name in file_names:
        cycle = bfs(file_name)
        if cycle:
            if shortest_cycle is None or len(cycle) < len(shortest_cycle):
                shortest_cycle = cycle

    if shortest_cycle:
        return ' '.join(shortest_cycle)
    else:
        return 'SHIP IT'

input = sys.stdin.read().splitlines()
n = int(input[0])
file_names = input[1].split()
sections = []
for i in range(n):
    section = input[2 + i * (int(input[2 + i].split()[1]) + 1):2 + (i + 1) * (int(input[2 + i].split()[1]) + 2)]
    sections.append(section)

print(find_shortest_cycle(n, file_names, sections))
